	raw, err := json.Marshal(harnesses.TextDeltaData{Text: agg.FinalText})
	if err != nil {
		return agg, err
	}
	ev := harnesses.Event{
		Type:     harnesses.EventTypeTextDelta,
		Sequence: *seq,
		Time:     time.Now().UTC(),
		Metadata: metadata,
		Data:     raw,
	}
